-- =============================================================================
-- ctf — reconcile schema with ORM models
-- =============================================================================
-- The hand-written 0001 migration drifted from the SQLAlchemy models, so the
-- services 500'd on columns/tables that were declared but never created
-- (e.g. challenges.walkthrough_markdown). Generated by diffing Base.metadata
-- against the live database. New columns are nullable so this is safe to
-- apply to populated tables.
-- =============================================================================

CREATE TABLE ctf.frozen_scoreboards (
	event_id UUID NOT NULL, 
	frozen_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	snapshot JSONB DEFAULT '[]' NOT NULL, 
	PRIMARY KEY (event_id), 
	FOREIGN KEY(event_id) REFERENCES ctf.events (id) ON DELETE CASCADE
);
CREATE TABLE ctf.event_announcements (
	id UUID NOT NULL, 
	event_id UUID NOT NULL, 
	posted_by UUID NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	body TEXT NOT NULL, 
	is_pinned BOOLEAN NOT NULL, 
	challenge_id UUID, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(event_id) REFERENCES ctf.events (id) ON DELETE CASCADE, 
	FOREIGN KEY(challenge_id) REFERENCES ctf.event_challenges (id) ON DELETE SET NULL
);
CREATE TABLE ctf.flag_submission_attempts (
	id UUID NOT NULL, 
	event_id UUID NOT NULL, 
	challenge_id UUID NOT NULL, 
	participant_id UUID NOT NULL, 
	user_id UUID NOT NULL, 
	accepted BOOLEAN NOT NULL, 
	submitted_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(event_id) REFERENCES ctf.events (id) ON DELETE CASCADE, 
	FOREIGN KEY(challenge_id) REFERENCES ctf.event_challenges (id) ON DELETE CASCADE, 
	FOREIGN KEY(participant_id) REFERENCES ctf.event_participants (id) ON DELETE CASCADE
);
CREATE TABLE ctf.hint_unlocks (
	id UUID NOT NULL, 
	event_id UUID NOT NULL, 
	challenge_id UUID NOT NULL, 
	participant_id UUID NOT NULL, 
	hint_id VARCHAR(64) NOT NULL, 
	point_deduction INTEGER NOT NULL, 
	unlocked_by_user_id UUID NOT NULL, 
	unlocked_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_hint_unlock UNIQUE (event_id, challenge_id, participant_id, hint_id), 
	FOREIGN KEY(event_id) REFERENCES ctf.events (id) ON DELETE CASCADE, 
	FOREIGN KEY(challenge_id) REFERENCES ctf.event_challenges (id) ON DELETE CASCADE, 
	FOREIGN KEY(participant_id) REFERENCES ctf.event_participants (id) ON DELETE CASCADE
);
